#!/usr/bin/env bash
set -euo pipefail
cd ~/freddy-fixit

echo "Freddy Fix It — cosmetic SEO + meta copy (2026-08-19)"
echo "Files: index.html, public/sitemap.xml"
echo

write_file () {
  # $1 = destination path, $2 = expected byte size, $3 = tmp file holding base64
  local dest="$1" want="$2" b64="$3" tmp="/tmp/ffwrite.$$"
  base64 -d < "$b64" > "$tmp"
  local got
  got=$(wc -c < "$tmp" | tr -d ' ')
  if [ "$got" != "$want" ]; then
    echo "REFUSING to write $dest — decoded $got bytes, expected $want"
    rm -f "$tmp"; exit 1
  fi
  mkdir -p "$(dirname "$dest")"
  cp "$tmp" "$dest"
  rm -f "$tmp"
  echo "  ok  $dest ($got bytes)"
}

cat > /tmp/ff.b64 <<'B64_EOF'

B64_EOF
write_file "index.html" 3890 /tmp/ff.b64

cat > /tmp/ff.b64 <<'B64_EOF'

B64_EOF
write_file "public/sitemap.xml" 8260 /tmp/ff.b64

rm -f /tmp/ff.b64

echo
echo "Building (this is the real check — stop here if it fails)…"
npx vite build

echo
git add -A
git commit -m "SEO: list auto-published blog posts and the contractor guide in the sitemap; align quote-count copy with the rest of the site" || echo "nothing to commit"
git push
echo
echo "✅ cosmetic SEO + meta copy pushed"
